"""Sweep for configured adapters and the credentials they declare (syzygy-bpyt.8.9).

Usage: python3 sweep.py <repo-root> <out.json>

Three populations, each with its denominator:
  1. adapter-registry entries under .syzygy/governance/declarations/adapter-registry/ (tracked JSON): every key path, and those
     whose key name matches CREDENTIAL_KEY;
  2. tracked implementation sources under packages/ and apps/ (.ts .mts .cts .js .mjs .cjs, tests excluded): lines matching
     CREDENTIAL_LINE, grouped by file;
  3. createCredentialProbe call sites in those sources, with the arguments each passes.
"""
import json
import re
import subprocess
import sys

CREDENTIAL_KEY = re.compile(r'credential|secret|token|password|apikey|api_key|privatekey', re.I)
CREDENTIAL_LINE = re.compile(
    r'credential|api[-_]?key|passw(?:or)?d|bearer|auth[-_]?token|access[-_]?token|private[-_]?key|\.token\b|secret[-_]?(?:file|path)',
    re.I,
)
SOURCE_SUFFIXES = ('.ts', '.mts', '.cts', '.js', '.mjs', '.cjs')
CALL = re.compile(r'createCredentialProbe\(([^()]*(?:\([^()]*\)[^()]*)*)\)')


def tracked(root, *pathspec):
    out = subprocess.run(['git', '-C', root, 'ls-files', '-z', '--', *pathspec], capture_output=True, check=True).stdout
    return sorted(p for p in out.decode('utf-8').split('\0') if p)


def key_paths(value, prefix=''):
    if isinstance(value, dict):
        for key, child in value.items():
            yield prefix + '.' + key, key
            yield from key_paths(child, prefix + '.' + key)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from key_paths(child, f'{prefix}[{index}]')


def main():
    root, out = sys.argv[1], sys.argv[2]
    head = subprocess.run(['git', '-C', root, 'rev-parse', 'HEAD'], capture_output=True, text=True, check=True).stdout.strip()

    registry = []
    for rel in tracked(root, '.syzygy/governance/declarations/adapter-registry'):
        if not rel.endswith('.json'):
            continue
        document = json.load(open(f'{root}/{rel}', encoding='utf-8'))
        paths = list(key_paths(document))
        registry.append({
            'file': rel,
            'entries': len(document.get('entries', [])),
            'entryIds': [entry.get('observerId') or entry.get('adapterId') or entry.get('id') for entry in document.get('entries', [])],
            'keyPaths': len(paths),
            'credentialNamedKeyPaths': [path for path, key in paths if CREDENTIAL_KEY.search(key)],
        })

    sources = [p for p in tracked(root, 'packages', 'apps') if p.endswith(SOURCE_SUFFIXES) and not re.search(r'\.test\.[cm]?[tj]s$', p)]
    hits = {}
    calls = []
    for rel in sources:
        text = open(f'{root}/{rel}', encoding='utf-8').read()
        for number, line in enumerate(text.split('\n'), 1):
            if CREDENTIAL_LINE.search(line):
                hits.setdefault(rel, []).append(number)
        for match in CALL.finditer(text):
            line = text.count('\n', 0, match.start()) + 1
            calls.append({'file': rel, 'line': line, 'arguments': match.group(1).strip()})

    json.dump({
        'commit': head,
        'registry': {'files': len(registry), 'entries': sum(r['entries'] for r in registry), 'detail': registry,
                     'credentialKeyPattern': CREDENTIAL_KEY.pattern},
        'implementationSources': {'files': len(sources), 'filesWithHits': len(hits), 'linePattern': CREDENTIAL_LINE.pattern,
                                  'hits': {rel: lines for rel, lines in sorted(hits.items())}},
        'probeCallSites': {'count': len(calls), 'calls': calls},
    }, open(out, 'w', encoding='utf-8'), indent=2)
    print(f'commit={head} registryFiles={len(registry)} sources={len(sources)} filesWithHits={len(hits)} probeCalls={len(calls)}')


if __name__ == '__main__':
    main()
